export function digitsum(n: number): number {
  let total = 0;
  for (let i = 0; i < n; i++) {
    let x = i;
    while (x > 1) {
      total += x % 10;
      x = Math.floor(x / 10);
    }
  }
  return total;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { digitsum } from "./digitsum.js";

test("digitsum", () => {
  assert.equal(digitsum(10), 45);
  assert.equal(digitsum(100), 900);
});
